<div class="d-flex justify-content-between align-items-center mb-4"><h1 class="h3 mb-0">Aktywacje</h1></div>
<div class="card shadow-sm"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>ID</th><th>Produkt</th><th>Licencja</th><th>Domena</th><th>Status</th><th>Aktywacja</th><th>Ostatni check</th><th></th></tr></thead><tbody><?php foreach ($activations as $activation): ?><tr><td><?= e((string) $activation['id']) ?></td><td><?= e($activation['product_name']) ?></td><td><code><?= e($activation['masked_key']) ?></code></td><td><?= e($activation['canonical_domain']) ?></td><td><?= e($activation['activation_status']) ?></td><td><?= e($activation['activated_at']) ?></td><td><?= e($activation['last_checked_at']) ?></td><td><?php if ($activation['activation_status'] === 'active'): ?><form method="post" action="/admin/activations/<?= e((string) $activation['id']) ?>/release"><input type="hidden" name="<?= e($csrfTokenName) ?>" value="<?= e($csrfToken) ?>"><button class="btn btn-sm btn-outline-danger">Zwolnij</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
